import React from "react";

// Function to copy the Figma data to the clipboard
const copyFigmaToClipboard = (figmaCode) => {
  const htmlData = `
    <html>
      <head>
        <meta http-equiv="content-type" content="text/html; charset=utf-8">
      </head>
      <body>
        <!--StartFragment-->
        ${figmaCode}  <!-- Dynamic Figma component data goes here -->
        <!--EndFragment-->
      </body>
    </html>
  `;

  const blob = new Blob([htmlData], { type: "text/html" });

  // Create a ClipboardItem with the Blob
  const item = new ClipboardItem({ "text/html": blob });

  // Use the Clipboard API to write the content to the clipboard
  navigator.clipboard
    .write([item])
    .then(() => {
      console.log("Figma component copied to clipboard!");
      alert("Figma component copied to clipboard!");
    })
    .catch((err) => {
      console.error("Failed to copy:", err);
      alert("Failed to copy Figma component.");
    });
};

const CopyFigmaComponentButton = ({
  figmaCode
}) => {
  return (
    <div>
      <button
        onClick={() => copyFigmaToClipboard(figmaCode)}
      >
        
        Copy to Clipboard
      </button>
    </div>
  );
};

